    "corpus_policies.py": """"Concrete corpus-conditioned research arms; no labels, categories or files."""

import method as base
from question_features import features, option_completion, reset_feature_cache


def profile_reuse(state):
    history = base._field(state, "generated_token_ids")
    budget = base.allowance(state)
    if budget < 2:
        return []
    f = features(base._field(state, "question"))
    if f["conservative"]:
        return base.reuse_tokens(history, min(2, budget), min_context=6)
    return base.reuse_tokens(history, budget)


def option_echo(state):
    history = base._field(state, "generated_token_ids")
    budget = base.allowance(state)
    if budget < 2 or not isinstance(history, (list, tuple)) or any(
            type(token) is not int or token < 0 for token in history):
        return []
    proposal = base._reuse_validated(list(history[-96:]), budget)
    if proposal:
        return proposal
    text = option_completion(base._field(state, "question"), base._field(state, "decoded_text"))
    return {"text": text} if text else []


def reset_policy_state():
    base.reset_policy_state()
    reset_feature_cache()
