    "question_features.py": """"Bounded, label-free public question parsing for research policy candidates."""

import re
from functools import lru_cache


INLINE = re.compile(r"(?:^|,\s+)([A-D]):\s*")
LINES = re.compile(r"^\(([A-D])\)\s*", re.MULTILINE)
NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:\s*%|\s*[A-Za-z]+)?")


def parse_options(question):
    """Reject ambiguous option markers rather than silently guessing a split."""
    if type(question) is not str or len(question) > 4096:
        return "unsupported", "", ()
    formats = []
    for marker, pattern, name in (("\nOptions: ", INLINE, "inline_colon"),
                                   ("\nChoices:\n", LINES, "multiline_parenthesis")):
        if question.count(marker) == 1:
            stem, body = question.split(marker)
            matches = list(pattern.finditer(body))
            if [m.group(1) for m in matches] == list("ABCD") and matches[0].start() == 0:
                options = tuple(body[m.end():matches[i + 1].start() if i < 3 else len(body)].strip()
                                for i, m in enumerate(matches))
                if all(options):
                    formats.append((name, stem, options))
    return formats[0] if len(formats) == 1 else ("unparsed", question, ())


@lru_cache(maxsize=16)
def _features(question):
    layout, stem, options = parse_options(question)
    live = tuple(o for o in options if o.casefold() != "nan")
    numeric = sum(bool(NUMBER.fullmatch(o)) for o in live)
    lengths = sorted(len(o) for o in live)
    median = ((lengths[(len(lengths) - 1) // 2] + lengths[len(lengths) // 2]) / 2
              if lengths else 0)
    return dict(layout=layout, stem=stem, options=options, live_options=len(live),
                numeric_options=numeric, median_option_chars=median,
                conservative=bool(options) and
                (len(live) <= 2 or numeric * 2 >= len(live) or median < 8))


def features(question):
    if type(question) is not str or len(question) > 4096:
        return dict(layout="unsupported", stem="", options=(), live_options=0,
                    numeric_options=0, median_option_chars=0, conservative=False)
    return _features(question)


def reset_feature_cache():
    _features.cache_clear()


ANCHOR = re.compile(r"(?:Answer:\s*|Final answer:\s*|The answer is\s+|The correct answer is\s+)"
                    r"\(?([A-D])\)?[.:]\s+(.*)\Z", re.DOTALL)


def _option_completion(question, decoded_text, allow_word_boundary):
    """Complete only a committed letter plus a substantial exact option echo."""
    if type(decoded_text) is not str or len(decoded_text) > 16384:
        return ""
    # Restrict to the current line: explanatory prose before it is irrelevant.
    line = decoded_text.rsplit("\n", 1)[-1]
    match = ANCHOR.fullmatch(line)
    if match is None:
        return ""
    options = features(question)["options"]
    if len(options) != 4:
        return ""
    option = options[ord(match.group(1)) - ord("A")]
    prefix = match.group(2)
    if (len(prefix) < 8 or len(re.findall(r"[^\W\d_]+", prefix)) < 2 or
            not option.startswith(prefix) or len(prefix) >= len(option) or
            not (prefix[-1].isspace() or
                 (allow_word_boundary and option[len(prefix)].isspace()))):
        return ""
    # Text length is a payload bound, not a prediction of tokenizer length.
    return option[len(prefix):len(prefix) + 64]


def option_completion(question, decoded_text):
    return _option_completion(question, decoded_text, True)


def option_completion_whitespace_only(question, decoded_text):
    """Preserved rejected controller rule for the boundary counterexample."""
    return _option_completion(question, decoded_text, False)
