    "method_before_diagnosis.py": """"A conservative, state-only speculative draft policy.

The policy has no access to the target model or tokenizer. It therefore only
offers a very short formatting continuation when the already generated text
contains an explicit answer label. All other prefixes use ordinary decoding.
"""

from __future__ import annotations

import re
from typing import Any, Optional


_MAX_VERIFIED_DRAFT = 32

# These forms are deliberately exact suffixes. The next token after each form
# is normally a separator, while answer content remains delegated to the target.
_SPACE_AFTER_LABEL = (
    "answer:",
    "final answer:",
    "the answer is:",
    "the correct answer is:",
)


def _field(state: Any, name: str, default: Any = None) -> Any:
    """Read either a mapping-style or attribute-style host state."""
    if isinstance(state, dict):
        return state.get(name, default)
    try:
        return getattr(state, name)
    except (AttributeError, TypeError):
        return default


def _nonnegative_int(value: Any) -> Optional[int]:
    """Coerce ordinary host values without letting malformed values escape."""
    if isinstance(value, bool):
        return int(value)
    try:
        number = int(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return number if number >= 0 else None


def _answer_label_continuation(text: str) -> Optional[str]:
    """Return a separator only for a recognizable answer-label suffix."""
    # A trailing separator means the target has already emitted the proposed
    # whitespace, so proposing another one would add avoidable risk.
    if not text or text[-1].isspace():
        return None

    folded = text.casefold().rstrip()
    for label in _SPACE_AFTER_LABEL:
        if folded == label or folded.endswith(" " + label):
            return " "

    # Models sometimes omit the colon after "answer is". The punctuation is
    # still a structural continuation, but only for a complete phrase at the end.
    if re.search(r"(?:^|\s)(?:the\s+)?(?:correct\s+)?answer\s+is$", folded):
        return ": "
    return None


def draft(state):
    """Return a bounded proposal, or ``[]`` for ordinary decoding.

    Empty and semantically unconstrained prefixes intentionally return an empty
    list. The host's tokenizer encodes the text object, so this policy never
    guesses token IDs from an unknown vocabulary.
    """
    if state is None:
        return []

    remaining = _nonnegative_int(_field(state, "remaining_tokens"))
    if remaining is None or remaining == 0:
        return []

    maximum = _nonnegative_int(_field(state, "maximum_draft_tokens", _MAX_VERIFIED_DRAFT))
    if maximum is None or maximum == 0:
        return []
    budget = min(_MAX_VERIFIED_DRAFT, remaining, maximum)
    if budget <= 0:
        return []

    decoded = _field(state, "decoded_text", "")
    if decoded is None:
        decoded = ""
    if not isinstance(decoded, str):
        try:
            decoded = str(decoded)
        except Exception:
            return []

    continuation = _answer_label_continuation(decoded)
    if continuation is None:
        return []

    # Both continuations are short; the explicit budget check keeps this safe if
    # the host supplies a very small allowance.
    if budget < 1 or (continuation == ": " and budget < 2):
        return []
    return {"text": continuation}
